#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Provisions the VPS deploy (issue #49): swapfile, Coolify, a Coolify-managed
# Postgres container, and the single-origin app image pulled from public GHCR.
# It walks the human through the VPS/dashboard steps and stores the captured
# values in the repo-root .env (git-ignored) — nothing is committed.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=6

banner "Provision the VPS deploy: Coolify + GHCR + on-VPS Postgres (issue #49)"

# ── Stage 1: VPS prep — swapfile as memory insurance ─────────────────────
stage "VPS: swapfile"
say "The box is small (1 vCPU / 2 GB RAM). A swapfile keeps a memory spike"
say "from OOM-killing Coolify or the app container. SSH into the VPS and run:"
say "  fallocate -l 2G /swapfile && chmod 600 /swapfile"
say "  mkswap /swapfile && swapon /swapfile"
say "  echo '/swapfile none swap sw 0 0' >> /etc/fstab"
step "Also confirm Docker is installed (Coolify's installer can do this for you)."
pause "Swapfile active? (check: free -h shows a Swap line)"

# ── Stage 2: install Coolify ──────────────────────────────────────────────
stage "Install Coolify"
open_url "https://coolify.io/docs/installation"
say "On the VPS, run Coolify's install script:"
say "  curl -fsSL https://cdn.coollabs.io/coolify/install.sh | bash"
step "Open http://<vps-hostname>:8000 and create the first admin account."
step "In Settings, check that the server is healthy (the local Docker server)."
ask COOLIFY_URL "Coolify dashboard URL (e.g. http://<vps-hostname>:8000):"
write_env COOLIFY_URL "$COOLIFY_URL"

# ── Stage 3: make the GHCR image public ───────────────────────────────────
stage "GHCR: make the package public"
say "CI pushes the image to ghcr.io/polarode/tichu-turnier on every push to"
say "main — but only after the first push to main. If the package doesn't"
say "exist yet, push to main first (this wizard can be re-run afterwards)."
open_url "https://github.com/polarode?tab=packages"
step "Open the 'tichu-turnier' package → Package settings."
step "Change visibility to Public (a one-time confirmation dialog)."
note "Public means the VPS pulls the image without any registry credentials."
pause "Package is public?"

# ── Stage 4: Postgres as a Coolify-managed container ──────────────────────
stage "Coolify: create the Postgres resource"
say "In the Coolify dashboard:"
step "Project → New resource → Docker Compose (or Database) → PostgreSQL 17."
step "Give it a persistent Docker volume for /var/lib/postgresql/data"
step "  (Coolify's database resources create one automatically)."
step "Note the generated credentials; set the database name to 'tichu_turnier'."
warn "Set user/password/db-name BEFORE the first start: POSTGRES_* env vars"
warn "only apply when the data directory is empty. Changing them in the UI"
warn "afterwards does not affect the running DB — later changes need an"
warn "ALTER USER inside the container or a volume wipe."
step "Set the port mapping so the app container can reach it over the"
step "  Coolify/Docker network by service name (e.g. postgres:5432)."
step "Pick a stable service name (e.g. 'postgres') — it is the hostname in"
step "  the app's JDBC URLs and survives resource recreation."
ask DB_USER "Postgres username:"
ask_secret DB_PASSWORD "Postgres password:"
ask DB_NAME "Database name:"   # default handled below
DB_NAME=${DB_NAME:-tichu_turnier}
note "JDBC URL (datasource AND Flyway — same host, see the runbook):"
note "  jdbc:postgresql://postgres:5432/$DB_NAME"
write_env DB_USER "$DB_USER"
write_env DB_PASSWORD "$DB_PASSWORD"
write_env DB_NAME "$DB_NAME"

# ── Stage 5: the app from GHCR ────────────────────────────────────────────
stage "Coolify: create the app resource from GHCR"
step "Project → New resource → Docker Image."
step "Image: ghcr.io/polarode/tichu-turnier:latest"
step "Port: 8080. Domain: the provider-assigned hostname (plain HTTP for now)."
step "Health check path: /health"
step "Enable auto-deploy so Coolify redeploys when a new image is pushed."
step "Environment variables (from $ENV_FILE):"
say "  SPRING_PROFILES_ACTIVE     = prod"
say "  SPRING_DATASOURCE_URL      = jdbc:postgresql://postgres:5432/$DB_NAME"
say "  SPRING_DATASOURCE_USERNAME = $DB_USER"
say "  SPRING_DATASOURCE_PASSWORD = (the password)"
say "  SPRING_FLYWAY_URL          = same as SPRING_DATASOURCE_URL"
say "  SPRING_FLYWAY_USERNAME     = $DB_USER"
say "  SPRING_FLYWAY_PASSWORD     = (the password)"
say "  APP_FRONTEND_URL           = http://<provider-hostname>"
say "  APP_AUTH_SESSION_COOKIE_SECURE = false   (plain HTTP until S10.7)"
say "  APP_AUTH_OWNER_EMAIL       = (the owner email)"
say "  APP_AUTH_OWNER_PASSWORD_HASH = (bcrypt hash; see provision-production.sh"
say "                               stage 2 for how to generate one)"
say "  JAVA_TOOL_OPTIONS          = -XX:MaxRAMPercentage=75"
ask APP_FRONTEND_URL "Paste the app's http:// URL:"
write_env APP_FRONTEND_URL "$APP_FRONTEND_URL"
pause "First deploy finished (log shows 'Migrating schema …' with no errors)?"

# ── Stage 6: verify ───────────────────────────────────────────────────────
stage "Verify the live app"
if curl -sf "$APP_FRONTEND_URL/health" | grep -q '"status":"UP"'; then
  printf '  %s✓ /health is UP%s\n' "$GREEN" "$RESET"
else
  warn "/health did not answer UP — check the Coolify deploy log."
fi
step "Open the URL: the SPA loads; log in at /admin with the owner credential."
step "Create some data, then restart the container — data survives (volume)."
step "Redeploy the app from Coolify — data survives."
step "Run the full checklist in deploy/README.md and record the results."
open_url "$APP_FRONTEND_URL"

finish
}

run_wizard "$@"; exit
